-- Quests recorded as they were picked up, collected from SavedVariables with
-- tools/harvest-quests.lua. The script rewrites this file but keeps hand
-- edits: remove a wrong record, or add after/afterTitle/needs/needsQuest/item*/turnIn*/find*/also/instead/during/leadsTo/class/profession/repeatable/patrols/legacy/holiday.
--
-- [questID] = { title, level, group, dungeon, zone, mapID, x, y, giver, patrols, fromItem, handIn, repeatable,
--               side, after, afterTitle, needs, needsQuest, needsQuestTitle, itemZone, itemMapID, itemX, itemY,
--               turnIn, turnInZone, turnInMapID, turnInX, turnInY, find, findZone, findMapID, findX, findY, findAlso,
--               instead, during, leadsTo, class,
--               races, profession, seeded, horde*/alliance* (zone, mapID, x, y, giver), also }
-- after = the quest that comes first; needs = free text for anything else it takes;
-- needsQuest/needsQuestTitle = the quest whose hand-in unlocks it, when that is not a chain,
--   or a list of them ({ 1, 2 } and { "One", "Two" }) when it takes them all;
-- itemZone/itemMapID/itemX/itemY = where the item it needs lies, e.g. a book; listed in itemZone, click marks it;
-- turnIn/turnInZone/turnInMapID/turnInX/turnInY = where it is handed in, when the quest only hints at it
--   (turnIn names the NPC or object; ctrl-click in the list when there is no item*);
-- find/findZone/findMapID/findX/findY = who or what the quest sends you to find, when the map does not show it
--   (ctrl-click in the list when there is no item*);
-- findAlso = { { find, zone, mapID, x, y }, ... }: more of them, when there are several; ctrl-click goes through them
-- instead = the alternative quest, when only one of the two can be done;
-- during = the quest it can only be taken while you have, e.g. a step in it;
-- leadsTo = the quest this one sends you to, when that one does not need it;
-- class = the classes that can take it, as the client's tokens ("DRUID", "WARRIOR PALADIN");
-- races = the races that can take it, as UnitRace's tokens ("Dwarf Gnome"), when not the whole side;
-- profession = the profession it takes, as the skill list names it ("Tailoring"),
--   or false when checked in play that the title's profession is not needed.
-- seeded = true: only known from DungeonLevelGuide's list, not yet seen in play.
-- handIn = true: never taken, handed straight in to the giver, who is where it was recorded.
-- side = false: both factions take it (seen recorded by both).
-- hordeZone/hordeMapID/hordeX/hordeY/hordeGiver (or alliance*): where that side takes it,
--   when it is not where the record says.
-- hordeAfter/hordeAfterTitle (or alliance*): the quest that comes first for that side.
-- listZone (or hordeListZone/allianceListZone) = the zone it is listed under, when not where it is taken,
--   e.g. taken in a zone that side does not see; the tooltip and the click still use zone/x/y.
-- also = { { zone, mapID, x, y, giver }, ... }: other givers somewhere else, as many as there are;
--   listed in each of their zones too.
-- repeatable = true: can be handed in again and again.
-- patrols = true: the giver walks a route; x, y is where it was taken.
-- dungeon = false: the game tags it as a dungeon quest, but it is done outside.
-- legacy = n: a Legacy reward, offered from level n on the Legacy Track; hidden below it.
-- holiday = "Hallow's End": only offered during that holiday; hidden the rest of the year.
